import{fromUserExtent as u,fromUserResolution as x,toUserExtent as l}from"./proj.js";export function all(n,e){return[[-1/0,-1/0,1/0,1/0]]}export function bbox(n,e){return[n]}export function tile(n){return(function(e,s,r){const i=n.getZForResolution(x(s,r)),o=n.getTileRangeForExtentAndZ(u(e,r),i),f=[],t=[i,0,0];for(t[1]=o.minX;t[1]<=o.maxX;++t[1])for(t[2]=o.minY;t[2]<=o.maxY;++t[2])f.push(l(n.getTileCoordExtent(t),r));return f})}
